# --- Load seed ---
with SEED.open() as f:
    data = json.load(f)

# Build set of existing IDs to avoid duplicates
existing = {f["id"] for f in data["features"]}
existing_rejected_names = {r["name"].lower() for r in data["rejected"]}

added = 0
for f in NEW_FEATURES:
    if f["id"] in existing:
        continue
    data["features"].append(f)
    existing.add(f["id"])
    added += 1

added_rejected = 0
for r in NEW_REJECTED:
    if r["name"].lower() in existing_rejected_names:
        continue
    data["rejected"].append(r)
    existing_rejected_names.add(r["name"].lower())
    added_rejected += 1

# --- Write back features.json ---
with SEED.open("w") as f:
    json.dump(data, f, indent=2, ensure_ascii=False)

# --- Build self-contained HTML by inlining the data ---
html_text = HTML_IN.read_text()

# Replace the fetch block with an inline assignment
fetch_block_re = re.compile(
    r"// Load features when script populates window\.FEATURES.*?$\s*}\);",
    re.DOTALL | re.MULTILINE,
)
inline_data = (
    "window.FEATURES = "
    + json.dumps(data["features"], ensure_ascii=False)
    + ";\n"
    + "window.REJECTED = "
    + json.dumps(data["rejected"], ensure_ascii=False)
    + ";\n"
    + "document.getElementById('loading-banner').style.display = 'none';\n"
    + "render();\nrenderRejected();"
)

if fetch_block_re.search(html_text):
    html_text = fetch_block_re.sub(inline_data, html_text)
else:
    # Idempotent: replace any prior inline assignment
    inline_re = re.compile(
        r"window\.FEATURES = .*?renderRejected\(\);", re.DOTALL
    )
    html_text = inline_re.sub(inline_data, html_text)

HTML_OUT.write_text(html_text)

print(f"Added {added} new features, {added_rejected} new rejected items.")
print(f"Total features: {len(data['features'])}, rejected: {len(data['rejected'])}.")
print(f"HTML written to {HTML_OUT}")
